"""Visibility, backpressure, and cancellation: individually composed diagrams."""
from atlas_figures import shell
LESSONS=[{"title":"Visibility needs a synchronization edge","text":"Suppose a worker stores the completed OCR result and then signals that it is ready. The reader must observe that signal through proper synchronization. The happens-before edge ensures earlier writes become visible; timing alone is not a substitute for synchronization."},{"title":"Immutable sharing and guarded mutation","text":"An immutable published result can be read by many threads without coordinating writes to that result. Mutable shared counters and collections require a safe protocol. Making a reference immutable does not make a mutable object behind it immutable."},{"title":"When arrivals exceed service capacity","text":"If ten jobs arrive per second but workers finish six, the unbounded waiting queue grows by approximately four each second until another limit is reached. A bounded queue caps memory and forces a clear overload response; it does not increase service rate."},{"title":"Cancellation propagates through a task family","text":"Structured concurrency ties child tasks to their parent scope. When the request is cancelled, the scope arranges cancellation of outstanding children and waits for cleanup as required by its runtime. But a network request may already have caused a side effect: cancellation is not a business rollback."}]
SVGS=["<text x=\"46\" y=\"47\">WRITER THREAD</text><text x=\"568\" y=\"47\">READER THREAD</text><path d=\"M166 55V285M704 55V285\" stroke=\"#8ba1a4\" stroke-dasharray=\"6 5\"/><rect x=\"59\" y=\"78\" width=\"259\" height=\"58\" rx=\"7\" fill=\"#dfeafb\"/><text x=\"188\" y=\"101\" text-anchor=\"middle\">write result = \"done\"</text><text x=\"188\" y=\"120\" text-anchor=\"middle\">ordinary data write</text><rect x=\"59\" y=\"170\" width=\"259\" height=\"58\" rx=\"7\" fill=\"#d7eee0\"/><text x=\"188\" y=\"204\" text-anchor=\"middle\">release / synchronized signal</text><rect x=\"566\" y=\"170\" width=\"268\" height=\"58\" rx=\"7\" fill=\"#d7eee0\"/><text x=\"700\" y=\"204\" text-anchor=\"middle\">acquire / synchronized read</text><rect x=\"566\" y=\"253\" width=\"268\" height=\"48\" rx=\"7\" fill=\"#dfeafb\"/><text x=\"700\" y=\"281\" text-anchor=\"middle\">observe result = \"done\"</text><path d=\"M318 199H566\" stroke=\"#38856c\" stroke-width=\"4\"/><text x=\"441\" y=\"184\" text-anchor=\"middle\">happens-before</text>","<rect x=\"43\" y=\"51\" width=\"370\" height=\"244\" rx=\"12\" fill=\"#edf6ef\" stroke=\"#5e9874\"/><text x=\"228\" y=\"80\" text-anchor=\"middle\">IMMUTABLE RESULT</text><rect x=\"116\" y=\"106\" width=\"225\" height=\"60\" fill=\"#c8e8d5\"/><text x=\"228\" y=\"141\" text-anchor=\"middle\">pages = (1, 2, 3)</text><path d=\"M228 166V204M228 204H116M228 204H341\" stroke=\"#3a8a65\" stroke-width=\"3\" fill=\"none\"/><text x=\"116\" y=\"231\" text-anchor=\"middle\">reader A</text><text x=\"341\" y=\"231\" text-anchor=\"middle\">reader B</text><rect x=\"470\" y=\"51\" width=\"389\" height=\"244\" rx=\"12\" fill=\"#fff3e9\" stroke=\"#bb8a64\"/><text x=\"664\" y=\"80\" text-anchor=\"middle\">MUTABLE COUNTER</text><rect x=\"555\" y=\"112\" width=\"220\" height=\"58\" fill=\"#f9ddc3\"/><text x=\"664\" y=\"147\" text-anchor=\"middle\">shared count = 7</text><rect x=\"499\" y=\"213\" width=\"330\" height=\"49\" fill=\"#f4c9bf\"/><text x=\"664\" y=\"244\" text-anchor=\"middle\">guard update with a mutex / atomic</text>","<text x=\"40\" y=\"43\">QUEUE DEPTH WITHOUT A LIMIT</text><path d=\"M92 61V247H549\" stroke=\"#5a7278\" stroke-width=\"3\" fill=\"none\"/><path d=\"M94 234L184 204L274 174L364 144L454 114L535 87\" stroke=\"#c47743\" stroke-width=\"4\" fill=\"none\"/><path d=\"M92 158H549\" stroke=\"#628b83\" stroke-width=\"2\" stroke-dasharray=\"7 5\"/><text x=\"336\" y=\"150\" text-anchor=\"middle\">queue capacity = 12</text><text x=\"480\" y=\"268\">time →</text><text x=\"596\" y=\"89\">ARRIVALS: 10/s</text><text x=\"596\" y=\"124\">SERVICE: 6/s</text><rect x=\"589\" y=\"158\" width=\"262\" height=\"116\" rx=\"10\" fill=\"#fae5d5\" stroke=\"#bd7b56\"/><text x=\"720\" y=\"187\" text-anchor=\"middle\">AT CAPACITY</text><text x=\"720\" y=\"218\" text-anchor=\"middle\">reject / defer input</text><text x=\"720\" y=\"245\" text-anchor=\"middle\">rather than grow forever</text>","<rect x=\"318\" y=\"42\" width=\"259\" height=\"55\" rx=\"10\" fill=\"#dceaf5\" stroke=\"#4d7eaa\"/><text x=\"447\" y=\"75\" text-anchor=\"middle\">PARENT · user upload</text><path d=\"M447 97V127M169 127H728M169 127V159M447 127V159M728 127V159\" stroke=\"#708b9c\" stroke-width=\"3\" fill=\"none\"/><rect x=\"64\" y=\"159\" width=\"210\" height=\"65\" rx=\"8\" fill=\"#e2ece0\"/><text x=\"169\" y=\"188\" text-anchor=\"middle\">OCR TASK</text><text x=\"169\" y=\"208\" text-anchor=\"middle\">cancel + cleanup</text><rect x=\"341\" y=\"159\" width=\"212\" height=\"65\" rx=\"8\" fill=\"#e2ece0\"/><text x=\"447\" y=\"188\" text-anchor=\"middle\">EXTRACT TASK</text><text x=\"447\" y=\"208\" text-anchor=\"middle\">cancel + cleanup</text><rect x=\"623\" y=\"159\" width=\"211\" height=\"65\" rx=\"8\" fill=\"#fae2c6\"/><text x=\"728\" y=\"188\" text-anchor=\"middle\">UPLOAD TASK</text><text x=\"728\" y=\"208\" text-anchor=\"middle\">side effect possible</text><path d=\"M447 97V155\" stroke=\"#b65c51\" stroke-width=\"5\" stroke-dasharray=\"6 5\"/><rect x=\"247\" y=\"256\" width=\"401\" height=\"45\" fill=\"#f7dfd9\"/><text x=\"447\" y=\"284\" text-anchor=\"middle\">Stop work ≠ undo a committed effect</text>"]
def drawing(n,j,k,index):
 x=LESSONS[index]
 return shell(n,j,k,x['title'],SVGS[index],x['text'],'Read the synchronization, load, or cancellation boundary shown.',height=320)
